class Solution {
    private boolean isPrime(int x) {
        if (x < 2 || x % 2 == 0) return x == 2;
        for (int d = 3; d * d <= x; d += 2) {
            if (x % d == 0) return false;
        }
        return true;
    }

    public int primePalindrome(int n) {
        if (n >= 8 && n <= 11) return 11;
        for (int L = 1; L <= 5; L++) {
            int start = (int) Math.pow(10, L - 1);
            int end = start * 10;
            for (int root = start; root < end; root++) {
                String s = Integer.toString(root);
                StringBuilder sb = new StringBuilder(s.substring(0, s.length() - 1)).reverse();
                int cand = Integer.parseInt(s + sb.toString());
                if (cand >= n && isPrime(cand)) return cand;
            }
        }
        return -1;
    }
}

var primePalindrome = function(n) {
    function isPrime(x) {
        if (x < 2 || x % 2 === 0) return x === 2;
        for (let d = 3; d * d <= x; d += 2) {
            if (x % d === 0) return false;
        }
        return true;
    }
    if (n >= 8 && n <= 11) return 11;
    for (let L = 1; L <= 5; L++) {
        const start = 10 ** (L - 1);
        const end = start * 10;
        for (let root = start; root < end; root++) {
            const s = String(root);
            const rev = s.slice(0, -1).split('').reverse().join('');
            const cand = parseInt(s + rev, 10);
            if (cand >= n && isPrime(cand)) return cand;
        }
    }
    return -1;
